//! FORK: Profile Bundle — a materialized local profile assembled from an ordered
//! list of subscription profiles.
//!
//! The generated file (`profiles/bundle-main.yaml`) is a plain Clash config, so
//! profile cards, generation and upstream code see an ordinary `type: local`
//! item. Fork-only state (ordered members + source fingerprints) lives in
//! `bundles/bundle-main.yaml`, outside `profiles.yaml`, so an upstream sync
//! cannot silently drop it.

use std::collections::BTreeMap;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{Context as _, Result, bail};
use clash_verge_draft::Draft;
use serde::{Deserialize, Serialize};
use serde_yaml_ng::Mapping;
use sha2::{Digest as _, Sha256};
use smartstring::alias::String;
use tokio::fs;

use crate::config::{IProfiles, PrfItem};
use crate::enhance::multi_merge::{self, ConflictEntry};
use crate::utils::{dirs, help, yaml_emitter};

mod migration;

pub use migration::{MigrationOutcome, MigrationPlan, migrate_legacy, plan_migration};

pub const BUNDLE_UID: &str = "bundle-main";
pub const BUNDLE_FILE: &str = "bundle-main.yaml";
pub const BUNDLE_META_FILE: &str = "bundle-main.yaml";
pub const BUNDLE_NAME: &str = "Profile Bundle";
pub const META_VERSION: u32 = 1;
pub const MIN_MEMBERS: usize = 2;

const GENERATED_HEADER: &str =
    "# Generated by Clash Verge Profile Bundle. Edit the bundle members instead of this file.\n";

/// Fork-only bundle metadata. Strict: unknown keys are rejected so a typo cannot
/// silently change which profiles get merged.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BundleMeta {
    pub version: u32,
    /// Ordered members; the first one is the base (primary) profile.
    pub members: Vec<String>,
    /// Member uid -> SHA-256 of the member file the bundle was generated from.
    #[serde(default)]
    pub sources: BTreeMap<String, String>,
    /// SHA-256 of the generated profile, so manual edits are detected and restored.
    #[serde(default)]
    pub generated_sha256: String,
    /// Conflicts from the last generation, re-published on startup so the UI can
    /// show them before the next regeneration.
    #[serde(default)]
    pub conflicts: Vec<ConflictEntry>,
    #[serde(default)]
    pub generated_at: u64,
}

/// Bytes needed to undo a failed bundle write.
#[derive(Debug, Clone, Default)]
pub struct BundleArtifacts {
    generated: Option<Vec<u8>>,
    meta: Option<Vec<u8>>,
}

#[derive(Debug)]
pub struct GeneratedBundle {
    pub yaml: std::string::String,
    pub meta: BundleMeta,
    pub conflicts: Vec<ConflictEntry>,
}

#[derive(Debug)]
pub struct RefreshOutcome {
    pub meta: BundleMeta,
    pub regenerated: bool,
    pub conflicts: Vec<ConflictEntry>,
}

#[derive(Debug, Default)]
pub struct TeardownOutcome {
    pub removed: bool,
    pub runtime_changed: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PrunePlan {
    Unchanged,
    Regenerate(Vec<String>),
    RemoveBundle,
}

pub fn is_bundle_uid(uid: &str) -> bool {
    uid == BUNDLE_UID
}

pub fn is_bundle_item(item: &PrfItem) -> bool {
    item.uid.as_deref() == Some(BUNDLE_UID)
}

pub fn generated_path() -> Result<PathBuf> {
    Ok(dirs::app_profiles_dir()?.join(BUNDLE_FILE))
}

pub fn meta_path() -> Result<PathBuf> {
    Ok(dirs::app_bundles_dir()?.join(BUNDLE_META_FILE))
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |duration| duration.as_secs())
}

pub(super) fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    let mut hex = std::string::String::with_capacity(digest.len() * 2);
    for byte in digest {
        use std::fmt::Write as _;
        let _ = write!(hex, "{byte:02x}");
    }
    hex.into()
}

pub fn parse_meta(text: &str) -> Result<BundleMeta> {
    let meta: BundleMeta = serde_yaml_ng::from_str(text).context("invalid bundle metadata")?;
    validate_meta(&meta)?;
    Ok(meta)
}

pub fn serialize_meta(meta: &BundleMeta) -> Result<std::string::String> {
    Ok(serde_yaml_ng::to_string(meta)?)
}

pub fn validate_meta(meta: &BundleMeta) -> Result<()> {
    if meta.version != META_VERSION {
        bail!(
            "unsupported bundle metadata version {} (expected {META_VERSION})",
            meta.version
        );
    }
    validate_member_list(&meta.members)
}

pub fn validate_member_list(members: &[String]) -> Result<()> {
    if members.len() < MIN_MEMBERS {
        bail!("a profile bundle needs at least {MIN_MEMBERS} members");
    }
    let mut seen = std::collections::HashSet::new();
    for uid in members {
        if uid.is_empty() {
            bail!("a profile bundle member uid is empty");
        }
        if is_bundle_uid(uid) {
            bail!("a profile bundle cannot include itself");
        }
        if !seen.insert(uid.as_str()) {
            bail!("duplicate profile bundle member '{uid}'");
        }
    }
    Ok(())
}

pub(super) fn validate_member_item(uid: &str, item: &PrfItem) -> Result<()> {
    if !matches!(item.itype.as_deref(), Some("local" | "remote")) {
        bail!("bundle member '{uid}' is not a subscription");
    }
    if item.file.is_none() {
        bail!("bundle member '{uid}' has no file");
    }
    Ok(())
}

/// Validate the ordered member list against the committed profile items.
pub fn validate_members(profiles: &IProfiles, members: &[String]) -> Result<()> {
    validate_member_list(members)?;
    for uid in members {
        let item = profiles
            .get_item(uid)
            .with_context(|| format!("bundle member '{uid}' no longer exists"))?;
        validate_member_item(uid, item)?;
    }
    Ok(())
}

fn member_path(uid: &str, item: &PrfItem) -> Result<PathBuf> {
    let file = item
        .file
        .as_ref()
        .with_context(|| format!("bundle member '{uid}' has no file"))?;
    Ok(dirs::app_profiles_dir()?.join(file.as_str()))
}

pub async fn load_meta() -> Result<Option<BundleMeta>> {
    let path = meta_path()?;
    if !fs::try_exists(&path).await.unwrap_or(false) {
        return Ok(None);
    }
    let text = fs::read_to_string(&path)
        .await
        .with_context(|| format!("failed to read {}", path.display()))?;
    parse_meta(&text).map(Some)
}

pub async fn save_meta(meta: &BundleMeta) -> Result<()> {
    let path = meta_path()?;
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .await
            .with_context(|| format!("failed to create {}", parent.display()))?;
    }
    help::save_yaml_str(&path, &serialize_meta(meta)?)
        .await
        .with_context(|| format!("failed to write {}", path.display()))
}

pub async fn write_generated(yaml: &str) -> Result<()> {
    help::save_yaml_str(&generated_path()?, yaml)
        .await
        .context("failed to write the generated bundle profile")
}

/// Generated profile first, metadata second: a crash in between leaves metadata
/// stale, which makes the next startup regenerate instead of trusting it.
pub async fn write(generated: &GeneratedBundle) -> Result<()> {
    write_generated(&generated.yaml).await?;
    save_meta(&generated.meta).await
}

pub async fn snapshot_artifacts() -> Result<BundleArtifacts> {
    Ok(BundleArtifacts {
        generated: read_optional(generated_path()?).await?,
        meta: read_optional(meta_path()?).await?,
    })
}

async fn read_optional(path: PathBuf) -> Result<Option<Vec<u8>>> {
    match fs::read(&path).await {
        Ok(bytes) => Ok(Some(bytes)),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(error).with_context(|| format!("failed to read {}", path.display())),
    }
}

pub async fn restore_artifacts(artifacts: &BundleArtifacts) -> Result<()> {
    restore_file(generated_path()?, artifacts.generated.as_deref()).await?;
    restore_file(meta_path()?, artifacts.meta.as_deref()).await
}

async fn restore_file(path: PathBuf, contents: Option<&[u8]>) -> Result<()> {
    match contents {
        Some(bytes) => {
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent).await?;
            }
            let text = std::str::from_utf8(bytes).context("bundle snapshot is not UTF-8")?;
            help::save_yaml_str(&path, text)
                .await
                .with_context(|| format!("failed to restore {}", path.display()))
        }
        None => {
            let _ = fs::remove_file(&path).await;
            Ok(())
        }
    }
}

pub async fn remove_artifacts() -> Result<()> {
    for path in [generated_path()?, meta_path()?] {
        match fs::remove_file(&path).await {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => {
                return Err(error).with_context(|| format!("failed to remove {}", path.display()));
            }
        }
    }
    Ok(())
}

/// Merge the member files in metadata order. The returned YAML is a plain
/// Clash profile; bundle state is not embedded in it.
pub async fn generate(profiles: &IProfiles, members: &[String]) -> Result<GeneratedBundle> {
    validate_members(profiles, members)?;

    let mut configs: Vec<Mapping> = Vec::with_capacity(members.len());
    let mut names: Vec<&str> = Vec::with_capacity(members.len());
    let mut sources = BTreeMap::new();
    for uid in members {
        let item = profiles.get_item(uid)?;
        let path = member_path(uid, item)?;
        let bytes = fs::read(&path)
            .await
            .with_context(|| format!("failed to read bundle member '{uid}'"))?;
        sources.insert(uid.clone(), sha256_hex(&bytes));
        let mapping = help::read_mapping(&path)
            .await
            .with_context(|| format!("failed to parse bundle member '{uid}'"))?;
        configs.push(mapping);
        names.push(item.name.as_deref().unwrap_or_default());
    }

    let (merged, conflicts) = multi_merge::multi_profile_merge(&configs, &names);
    let body = yaml_emitter::to_mihomo_config_string(&merged).context("failed to serialize the bundle profile")?;
    let yaml = format!("{GENERATED_HEADER}{body}");
    Ok(GeneratedBundle {
        meta: BundleMeta {
            version: META_VERSION,
            members: members.to_vec(),
            sources,
            generated_sha256: sha256_hex(yaml.as_bytes()),
            conflicts: conflicts.clone(),
            generated_at: now_secs(),
        },
        yaml,
        conflicts,
    })
}

pub async fn is_stale(profiles: &IProfiles, meta: &BundleMeta) -> Result<bool> {
    if profiles.get_item(BUNDLE_UID).is_err() {
        return Ok(true);
    }
    let Ok(generated_bytes) = fs::read(generated_path()?).await else {
        return Ok(true);
    };
    if meta.generated_sha256.is_empty() || meta.generated_sha256.as_str() != sha256_hex(&generated_bytes).as_str() {
        return Ok(true);
    }
    for uid in &meta.members {
        let Ok(item) = profiles.get_item(uid) else {
            return Ok(true);
        };
        if validate_member_item(uid, item).is_err() {
            return Ok(true);
        }
        let Ok(path) = member_path(uid, item) else {
            return Ok(true);
        };
        let Ok(bytes) = fs::read(&path).await else {
            return Ok(true);
        };
        let current = sha256_hex(&bytes);
        if meta.sources.get(uid).map(String::as_str) != Some(current.as_str()) {
            return Ok(true);
        }
    }
    Ok(false)
}

pub async fn is_member(uid: &str) -> Result<bool> {
    Ok(load_meta()
        .await?
        .is_some_and(|meta| meta.members.iter().any(|member| member == uid)))
}

/// Regenerate the bundle artifacts, replacing the previous generated file and
/// metadata atomically (each file), and publish the latest conflicts.
pub async fn regenerate(profiles: &IProfiles, members: &[String]) -> Result<GeneratedBundle> {
    let generated = generate(profiles, members).await?;
    write(&generated).await?;
    multi_merge::publish_conflicts(generated.conflicts.clone());
    Ok(generated)
}

/// Refresh the generated profile when a source member changed (or unconditionally
/// when `force`). Returns `None` when no bundle exists.
pub async fn refresh(profiles: &IProfiles, force: bool) -> Result<Option<RefreshOutcome>> {
    let Some(meta) = load_meta().await? else {
        return Ok(None);
    };
    if !force && !is_stale(profiles, &meta).await? {
        multi_merge::publish_conflicts(meta.conflicts.clone());
        return Ok(Some(RefreshOutcome {
            conflicts: meta.conflicts.clone(),
            meta,
            regenerated: false,
        }));
    }
    let generated = generate(profiles, &meta.members).await?;
    write(&generated).await?;
    multi_merge::publish_conflicts(generated.conflicts.clone());
    Ok(Some(RefreshOutcome {
        meta: generated.meta,
        regenerated: true,
        conflicts: generated.conflicts,
    }))
}

pub async fn refresh_if_stale(profiles: &IProfiles) -> Result<Option<RefreshOutcome>> {
    refresh(profiles, false).await
}

/// Add or overwrite the single bundle item. Keeps an existing display name and
/// removes duplicate bundle uids; the generated file itself is written elsewhere.
pub fn upsert_item(profiles: &mut IProfiles) -> bool {
    let now = chrono::Local::now().timestamp() as usize;
    let items = profiles.items.get_or_insert_with(Vec::new);
    let mut seen = false;
    items.retain(|item| {
        if !is_bundle_item(item) {
            return true;
        }
        if seen {
            return false;
        }
        seen = true;
        true
    });

    if let Some(item) = items.iter_mut().find(|item| is_bundle_item(item)) {
        item.itype = Some("local".into());
        item.file = Some(BUNDLE_FILE.into());
        item.updated = Some(now);
        item.url = None;
        item.selected = None;
        item.extra = None;
        item.option = None;
        item.home = None;
        if item.name.is_none() {
            item.name = Some(BUNDLE_NAME.into());
        }
        false
    } else {
        items.push(PrfItem {
            uid: Some(BUNDLE_UID.into()),
            itype: Some("local".into()),
            name: Some(BUNDLE_NAME.into()),
            file: Some(BUNDLE_FILE.into()),
            updated: Some(now),
            ..PrfItem::default()
        });
        true
    }
}

/// What deleting a profile must do to the bundle metadata.
pub fn plan_prune(meta: &BundleMeta, deleted: &str) -> PrunePlan {
    if !meta.members.iter().any(|member| member == deleted) {
        return PrunePlan::Unchanged;
    }
    let remaining: Vec<String> = meta
        .members
        .iter()
        .filter(|member| member.as_str() != deleted)
        .cloned()
        .collect();
    if remaining.len() < MIN_MEMBERS {
        PrunePlan::RemoveBundle
    } else {
        PrunePlan::Regenerate(remaining)
    }
}

/// Remove the bundle item plus generated file and metadata, leaving members
/// untouched. Returns whether the active profile changed.
pub async fn teardown(profiles: &Draft<IProfiles>) -> Result<TeardownOutcome> {
    let snapshot = profiles.latest_arc();
    let was_current = snapshot.current.as_deref() == Some(BUNDLE_UID);
    let has_item = snapshot.get_item(BUNDLE_UID).is_ok();
    drop(snapshot);

    if has_item {
        let plan = profiles
            .with_data_modify(|mut candidate| async move {
                let plan = candidate.plan_delete_item(BUNDLE_UID)?;
                candidate.save_file().await?;
                Ok((candidate, plan.1))
            })
            .await?;
        plan.cleanup().await;
    }
    remove_artifacts().await?;
    multi_merge::publish_conflicts(Vec::new());
    Ok(TeardownOutcome {
        removed: has_item,
        runtime_changed: was_current && has_item,
    })
}

